import java.util.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
/** Only actual fresh-source finite nonthrowing GOTO chains may be bypassed. */
public final class SourceLexicalSwitchTrampolineProof implements Opcodes {
 static LabelNode follow(MethodNode m,LabelNode label){var seen=new HashSet<Integer>();LabelNode result=label;int last=-1;while(true){int p=ExecutableVerify.target(m,result);ExecutableVerify.need(seen.add(p),"source-only trampoline cycle rejected");var ops=LeafSource.ops(m);ExecutableVerify.need(p>=0&&p<ops.size(),"actual source target exists");if(!(ops.get(p)instanceof JumpInsnNode j)||j.getOpcode()!=GOTO)return result;int target=ExecutableVerify.target(m,j.label);ExecutableVerify.need(target>=0&&target<ops.size(),"actual source lexical target exists; finite nonthrowing GOTO chain bounded by visited-set; source whole-CFG symbolic pre/post proof remains mandatory");for(var h:m.tryCatchBlocks)ExecutableVerify.need(p<ExecutableVerify.target(m,h.start)||p>=ExecutableVerify.target(m,h.end),"trampoline outside actual source protected range");result=j.label;last=p;}}
 static boolean same(Frame<SourceValue>a,Frame<SourceValue>b){return SourceContinuationProof.same(a,b);}
 static Map<String,Object> lexical(MethodNode m)throws Exception{ExecutableVerify.need(m.tryCatchBlocks.isEmpty(),"finite switch trampoline family requires no implicit source handlers");var ops=LeafSource.ops(m);var beforeOps=ExecutableVerify.ops(m);var values=new SourceLifetimeRemapProof.Values();var before=new Analyzer<>(values).analyze("source/fresh",m);var changed=new HashSet<Integer>();var rows=new ArrayList<Object>();for(int p=0;p<ops.size();p++){var n=ops.get(p);if(n instanceof JumpInsnNode j){if(j.getOpcode()==JSR)throw new AssertionError("no legacy source subroutine");var old=j.label;var target=follow(m,old);if(old!=target){j.label=target;changed.add(p);rows.add(CFGSource.map("source_edge_ordinal",p,"opcode",n.getOpcode(),"old_target",ExecutableVerify.target(m,old),"new_target",ExecutableVerify.target(m,target)));}}else if(n instanceof TableSwitchInsnNode t){var old=t.dflt;t.dflt=follow(m,t.dflt);boolean change=old!=t.dflt;for(int i=0;i<t.labels.size();i++){old=t.labels.get(i);var target=follow(m,old);t.labels.set(i,target);change|=old!=target;}if(change){changed.add(p);rows.add(CFGSource.map("source_edge_ordinal",p,"opcode",n.getOpcode(),"all_actual_case_and_default_targets_forwarded",true));}}else if(n instanceof LookupSwitchInsnNode t){var old=t.dflt;t.dflt=follow(m,t.dflt);boolean change=old!=t.dflt;for(int i=0;i<t.labels.size();i++){old=t.labels.get(i);var target=follow(m,old);t.labels.set(i,target);change|=old!=target;}if(change){changed.add(p);rows.add(CFGSource.map("source_edge_ordinal",p,"opcode",n.getOpcode(),"all_actual_case_and_default_targets_forwarded",true));}}}
  var after=new Analyzer<>(values).analyze("source/fresh",m);int raw=0,ordinal=0,checked=0;var afterOps=ExecutableVerify.ops(m);for(var n:m.instructions){if(n.getOpcode()>=0){if(!changed.contains(ordinal))ExecutableVerify.need(beforeOps.get(ordinal).equals(afterOps.get(ordinal)),"every unselected source opcode operand target exact");if(n.getOpcode()!=GOTO){ExecutableVerify.need(same(before[raw],after[raw]),"every retained opcode incoming symbolic locals/stack exact");if(before[raw]!=null){var a=new Frame<SourceValue>(before[raw]);var b=new Frame<SourceValue>(after[raw]);values.tape=new ArrayList<>();a.execute(n,values);var consumed=List.copyOf(values.tape);values.tape=new ArrayList<>();b.execute(n,values);ExecutableVerify.need(consumed.equals(values.tape)&&same(a,b),"every retained consumer producer width/order and outgoing stack/locals exact");}checked++;}ordinal++;}raw++;}return CFGSource.map("sites",rows,"checked_retained_source_opcodes",checked,"actual_fresh_source_only",true,"original_Code_frames_generation_oracle",false,"all_actual_switch_keys_default_and_selector_preserved",true,"whole_source_before_after_symbolic_dataflow_exact",true,"no_runtime_PC_state",true);
 }
}
